<?php
require_once __DIR__ . '/includes/functions.php';require_once __DIR__ . '/config/database.php';require_once __DIR__ . '/includes/mailer.php';
if(empty($_SESSION['pending_user_id'])){redirect('login.php');}$pdo=db();$userStmt=$pdo->prepare('SELECT * FROM users WHERE id=?');$userStmt->execute([$_SESSION['pending_user_id']]);$pendingUser=$userStmt->fetch();if(!$pendingUser){unset($_SESSION['pending_user_id'],$_SESSION['pending_email']);redirect('login.php');}$error=null;$message=null;
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();if(!rate_limit('otp:'.($_SESSION['pending_user_id']??'unknown'),12,900)){$error='Too many OTP attempts. Request a new code later.';}$action=$_POST['action']??'verify';if($action==='resend'){$code=(string)random_int(100000,999999);$pdo->prepare('UPDATE login_challenges SET used_at=NOW() WHERE user_id=? AND used_at IS NULL')->execute([$pendingUser['id']]);$pdo->prepare('INSERT INTO login_challenges (user_id,code_hash,expires_at) VALUES (?,?,DATE_ADD(NOW(),INTERVAL 10 MINUTE))')->execute([$pendingUser['id'],password_hash($code,PASSWORD_DEFAULT)]);$message=send_login_otp($pendingUser['email'],$code)?'A new verification code was sent.':'The verification email could not be sent.';}else{$stmt=$pdo->prepare('SELECT * FROM login_challenges WHERE user_id=? AND used_at IS NULL AND expires_at>NOW() ORDER BY id DESC LIMIT 1');$stmt->execute([$pendingUser['id']]);$challenge=$stmt->fetch();$code=trim($_POST['code']??'');if(!$challenge){$error='This code expired. Request a new code.';}elseif((int)$challenge['attempts']>=5){$error='Too many attempts. Request a new code.';}elseif(!password_verify($code,$challenge['code_hash'])){$pdo->prepare('UPDATE login_challenges SET attempts=attempts+1 WHERE id=?')->execute([$challenge['id']]);$error='Incorrect verification code.';}else{$pdo->prepare('UPDATE login_challenges SET used_at=NOW() WHERE id=?')->execute([$challenge['id']]);$pdo->prepare('UPDATE users SET last_login_at=NOW() WHERE id=?')->execute([$pendingUser['id']]);audit_action('login_success','users',$pendingUser['id'],'Gmail OTP verified');$_SESSION['user']=$pendingUser;unset($_SESSION['pending_user_id'],$_SESSION['pending_email']);redirect($pendingUser['role']==='resident'?'resident_portal.php':'index.php');}}}
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Email verification · Barangay Information System</title><link rel="stylesheet" href="assets/app.css"></head><body class="login-page"><div class="login-card"><div class="brand login-brand"><div class="brand-mark"><span></span><span></span></div><div><strong>Barangay</strong><small>information system</small></div></div><div class="eyebrow">Email verification</div><h1>Check your inbox.</h1><p class="login-copy">We sent a six-digit code to <strong><?= h($_SESSION['pending_email']) ?></strong>. It expires in 10 minutes.</p><?php if($error): ?><div class="flash error"><?= h($error) ?></div><?php endif; ?><?php if($message): ?><div class="flash success"><?= h($message) ?></div><?php endif; ?><form method="post" class="login-form"><input type="hidden" name="csrf" value="<?= h(csrf_token()) ?>"><input type="hidden" name="action" value="verify"><label>One-time code<input name="code" inputmode="numeric" pattern="[0-9]{6}" minlength="6" maxlength="6" required autofocus></label><button class="primary-button full-button">Verify and sign in</button></form><form method="post" class="otp-resend"><input type="hidden" name="csrf" value="<?= h(csrf_token()) ?>"><input type="hidden" name="action" value="resend"><button class="text-button">Send a new code</button><a class="text-button" href="logout.php">Cancel</a></form></div></body></html>
